#ifndef _PUBLIC
#define _PUBLIC

#define DMX_FLAG       1

typedef enum
{
   K_OK,
   K_NEXTFRAME,
   K_SKIPALL,
   K_EXITDOS
}KEYOPTS;

typedef enum
{
   R_YESNO,
   R_QUANTITY
}ASKBUY;

typedef struct
{
   BYTE  b1;
   BYTE  b2;
   BYTE  b3;
   BYTE  b4;
   SHORT px;
   SHORT py;
   SHORT playerpic;
   SHORT fil;
}RECORD;

typedef struct
{
   CHAR        name [ 20 ];
   CHAR        callsign [ 12 ];
   INT         id_pic;
   DWORD       score;                  // MONEY/POINTS
   INT         sweapon;                // CURENT SPECIAL WEAPON
   INT         cur_game;               // CURRENT GAME
   INT         game_wave[3];           // CURRENT WAVE
   INT         numobjs;                // NUMBER OF OBJECTS TO FOLLOW
   INT         diff[4];                // DIFFICULTY LEVEL
   BOOL        trainflag;
   BOOL        fintrain;
}PLAYEROBJ;

#define             END_DURATION ( 20 * 3 )
#define             END_EXPLODE  ( 24 )
#define             END_FLYOFF   ( 20 * 2 )

#define  DIFF_0   0  // TRAINING MODE
#define  DIFF_1   1  // EASY MODE
#define  DIFF_2   2  // NORMAL MODE
#define  DIFF_3   3  // HARD MODE

#define GAME1 ( gameflag[0] )
#define GAME2 ( gameflag[1] )
#define GAME3 ( gameflag[2] + gameflag[3] )

#define SHIELD_COLOR_RUN 9
#define SHIELD_LOW       10

#define PLAYERWIDTH  32
#define PLAYERHEIGHT 32
#define PLAYERMINX   5
#define PLAYERMAXX   314
#define PLAYERINITX  160-(PLAYERWIDTH/2)
#define PLAYERINITY  160

#define MINPLAYERY   0
#define MAXPLAYERY   160
  
#define GREEN        100
#define RED          34
#define YELLOW       50
  
#define MAP_ABORT    -1
#define MAP_NEXT     -2

//#define MAX_BADGUYS  300
#define MAX_ONSCREEN 30

/***************************************************************************
   InitMobj() - Inits an object to be moved
 ***************************************************************************/
VOID
InitMobj(
MOVEOBJ * cur              // INPUT : pointer to MOVEOBJ
);

/***************************************************************************
   MoveMobj() - gets next postion for an Object
 ***************************************************************************/
VOID
MoveMobj(
MOVEOBJ * cur              // INPUT : pointer to MOVEOBJ
);

/***************************************************************************
   MoveSobj() - gets next postion for an Object at speed
 ***************************************************************************/
INT
MoveSobj(
MOVEOBJ * cur,             // INPUT : pointer to MOVEOBJ
INT       speed            // INPUT : speed to plot at
);

/***************************************************************************
AskExit () - Opens Windows and Askes if USer wants 2 quit
 ***************************************************************************/
VOID
AskExit (
VOID
);

/***************************************************************************
Do_Game () - The main game thing this is it dude
 ***************************************************************************/
BOOL           // TRUE=Aborted, FALSE = timeout
Do_Game (
VOID
);

extern PLAYEROBJ     plr               ;
extern INT           choose_special [] ;
extern INT           cur_special   ;
extern INT           player_cx     ;
extern INT           player_cy     ;
extern INT           playerx       ;
extern INT           playery       ;
extern INT           playerbasepic ;
extern INT           playerpic     ;
extern INT           numbadguys    ;
extern INT           cur_game      ;
extern INT           game_wave[4]  ;
extern MAZELEVEL *   ml            ;
  
extern BYTE * palette;
extern INT    o_engine [];
extern INT    o_gun1 [];
extern INT    o_gun2 [];
extern INT    o_gun3 [];
extern FLATS * flatlib [];
extern BOOL   startfadeflag;
extern BYTE * patch1;  
extern BYTE * patch2;  
extern BOOL   end_wave;
extern INT    gl_cnt;
extern BOOL   testflag;
extern BOOL   gameflag[];
extern INT    startendwave;
extern BOOL   reg_flag;
extern BOOL   lowmem_flag;
extern INT    curplr_diff;
extern BOOL   bday_flag;
extern INT    bday_num;
extern INT    demo_flag;

#endif



#define MAX_FLIGHT      30

#define MAP_ROWS        150
#define MAP_ONSCREEN    8
#define MAP_COLS        9
#define MAP_BLOCKSIZE   32
#define MAP_BOTTOM      200 - 18
#define MAP_TOP         2
#define MAP_LEFT        16
#define MAP_RIGHT       ( 320 - 16 )
#define MAP_SIZE        ( MAP_ROWS * MAP_COLS )

#define MAX_TILES       2048
#define MAX_GUNS        24

#define ENGINE_COLOR    254
#define SHOT_COLOR      255

typedef struct
{
   INT   x;
   INT   y;
   INT   x2;
   INT   y2;
   INT   delx;
   INT   dely;
   INT   addx;
   INT   addy;
   INT   maxloop;
   INT   err;
   BOOL  done;
}MOVEOBJ;

// ENEMY SHIPS
// SHOOT
// MOVE
// CRASH INTO PLAYER
// ANIMATED
// TAKE DAMAGE
// SKY/GROUND

typedef enum
{
   F_REPEAT,
   F_LINEAR,
   F_KAMI,
   F_GROUND,
   F_GROUNDLEFT,
   F_GROUNDRIGHT,
}FLIGHT_TYPE;

typedef struct
{
   INT          linkflat;
   SHORT        bonus;
   SHORT        bounty;
}FLATS;                 

typedef struct
{
   SHORT        flats;
   SHORT        fgame;
}MAZEDATA;               

typedef struct
{
   DWORD       sizerec;
   DWORD       spriteoff;
   INT         numsprites;
   MAZEDATA    map[ MAP_SIZE ];
}MAZELEVEL;

typedef enum
{
   GANIM_NORM,
   GANIM_SHOOT,
   GANIM_MULTI
}ANIMTYPE;

typedef enum
{
   EXP_AIRSMALL1, // 0  
   EXP_AIRMED,    // 1 NORMAL AIR    ( norm )
   EXP_AIRLARGE,  // 2 bigger that 32 by 32
   EXP_GRDSMALL,  // 3 smaller than 32 by 32          
   EXP_GRDMED,    // 4 NORMAL GROUND ( norm )
   EXP_GRDLARGE,  // 5 bigger than 32 by 32
   EXP_BOSS,      // 6 BIG BOSS SHIP ( AIR ) 
   EXP_PERSON,    // 7 ONE LITTLE PERSON BLWING UP
   EXP_ENERGY,    // 8 ENERGY SHIP BLOWING UP
   EXP_PLATOON,   // 9 ONE LITTLE PERSON BLWING UP
   EXP_AIRSMALL2  // 10  
}EXP_TYPE;

typedef struct
{
   CHAR        iname[16];              // ITEM NAME
   DWORD       item;                   // * GLB ITEM #
   INT         bonus;                  // BONUS # ( -1 == NONE )
   EXP_TYPE    exptype;                // EXPLOSION TYPE           
   INT         shotspace;              // SLOWDOWN SPEED
   BOOL        ground;                 // IS ON GROUND
   BOOL        suck;                   // CAN SUCK WEAPON AFFECT 
   INT         frame_rate;             // FRAME RATE
   INT         num_frames;             // NUM FRAMES
   INT         countdown;              // COUNT DOWN TO START ANIM
   INT         rewind;                 // FRAMES TO REWIND
   ANIMTYPE    animtype;               // FREE SPACE FOR LATER USE
   BOOL        shadow;                 // USE SHADOW ( TRUE/FALSE )
   INT         bossflag;               // SHOULD THIS BE CONSIDERED A BOSS
   INT         hits;                   // HIT POINTS
   INT         money;                  // $$ AMOUNT WHEN KILLED
   INT         shootstart;             // SHOOT START OFFSET
   INT         shootcnt;               // HOW MANY TO SHOOT
   INT         shootframe;             // FRAME RATE TO SHOOT
   INT         movespeed;              // MOVEMENT SPEED
   INT         numflight;              // NUMBER OF FLIGHT POSITIONS
   INT         repos;                  // REPEAT TO POSITION
   FLIGHT_TYPE flighttype;             // FLIGHT TYPE
   INT         numguns;                // NUMBER OF GUNS
   INT         numengs;                // NUMBER OF ENGINES
   INT         sfx;                    // SFX # TO PLAY
   INT         song;                   // SONG # TO PLAY
   SHORT       shoot_type[MAX_GUNS];   // ENEMY SHOOT TYPE
   SHORT       engx[MAX_GUNS];         // X POS ENGINE FLAME
   SHORT       engy[MAX_GUNS];         // Y POS ENGINE FLAME
   SHORT       englx[MAX_GUNS];        // WIDTH OF ENGINE FLAME
   SHORT       shootx[MAX_GUNS];       // X POS SHOOT FROM
   SHORT       shooty[MAX_GUNS];       // Y POS SHOOT FROM
   SHORT       flightx[MAX_FLIGHT];    // FLIGHT X POS
   SHORT       flighty[MAX_FLIGHT];    // FLIGHT Y POS
}SPRITE;

typedef struct
{
   INT    link;
   INT    slib;
   INT    x;
   INT    y;
   INT    game;
   DWORD level;
}CSPRITE;



#define MAX_SHOTS 70

#ifndef  _OBJAPI
#include "objects.h"
#endif

#ifndef _SHOTSAPI
#define _SHOTSAPI

typedef enum
{
   S_ALL,
   S_AIR,
   S_GROUND,
   S_GRALL,
   S_GTILE,
   S_SUCK
}HIT_TYPE;

typedef enum
{
   S_SHOOT,
   S_LINE,
   S_BEAM
}BEAM_TYPE;

typedef struct 
{
   DWORD             lumpnum;          // LUMPNUM OF PIC(S)
   BYTE *            pic[ 10 ];        // POINTER TO PIC
   BOOL              shadow;           // SHADOW ON/OFF
   OBJ_TYPE          type;             // SHOT TYPE
   INT               hits;             // DAMAGE SHOT WILL DO
   INT               speed;            // START SPEED
   INT               maxspeed;         // MAXIMUM SPEED
   INT               startframe;       // START ANIM ON FRAME
   INT               numframes;        // NUMBER OF FRAMES OF ANIM
   INT               shoot_rate;       // SHOOT EVERY (N) FRAMES
   INT               cur_shoot;        // HOLDS FRAME COUNT DOWN
   BOOL              delayflag;        // DEALAYED ANIM START
   BOOL              smoke;            // SMOKE TRAIL
   BOOL              use_plot;         // TRUE = PLOT X,Y ( SLOWER )
   BOOL              move_flag;        // DOES SHOT NEED MOVEMENT
   HIT_TYPE          ht;               // SHOT HIT TYPE ( AIR/GROUND )
   BOOL              fplrx;            // FOLLOW PLAYER X POS
   BOOL              fplry;            // FOLLOW PLAYER Y POS
   BOOL              meffect;          // TRACK MOVE TO FIND HIT ?
   BEAM_TYPE         beam;             // BEAM WEAPON TYPE
   GFX_PIC *         h;
   INT               hlx;
   INT               hly;
}SHOT_LIB;

typedef struct SHOTS_S
{
