PRIVATE SPRITE_SHIP *   free_enemy;
PRIVATE CSPRITE *       end_enemy       = NUL;
PRIVATE CSPRITE *       cur_enemy       = NUL;
PUBLIC  BOOL            end_waveflag    = FALSE;
PRIVATE DWORD           spriteitm [ 4 ] = { SPRITE1_ITM,
                                            SPRITE2_ITM,
                                            SPRITE3_ITM,
                                            SPRITE4_ITM
                                            };


PUBLIC   INT   g_numslibs;

/***************************************************************************
   MoveEobj() - gets next postion for an Object at speed
 ***************************************************************************/
INT
MoveEobj(
MOVEOBJ * cur,             // INPUT : pointer to MOVEOBJ
INT       speed            // INPUT : speed to plot at
)
{
   if ( speed == 0 ) return ( 0 );

   if ( cur->delx >= cur->dely )
   {
      while ( speed )
      {
         speed--;
         cur->maxloop--;

         if ( cur->maxloop == 0 )
         {
            cur->done = TRUE;
            return ( speed );
         }

         cur->x += cur->addx;
         cur->err += cur->dely;
  
         if ( cur->err > 0 )
         {
            cur->y += cur->addy;
            cur->err -= cur->delx;
         }
      }
   }
   else
   {
      while ( speed )
      {
         speed--;
         cur->maxloop--;

         if ( cur->maxloop == 0 )
         {
            cur->done = TRUE;
            return ( speed );
         }

         cur->y += cur->addy;
         cur->err += cur->delx;
  
         if ( cur->err > 0 )
         {
            cur->x += cur->addx;
            cur->err -= cur->dely;
         }
      }
   }
  
   if ( cur->maxloop < 1 )
      cur->done = TRUE;

   return ( speed );
}

/***************************************************************************
ENEMY_FreeSprites () - Free Memory Used by Sprites use in last level
 ***************************************************************************/
VOID
ENEMY_FreeSprites (
VOID
)
{
   INT      loop, i;
   SPRITE * curlib;
   CSPRITE * curfld;

   for ( loop = 0; loop < 4; loop++ )
   {
      if ( spriteflag [ loop ] )
      {
         GLB_FreeItem ( spriteitm [ loop ] );
      }
   }

   for ( loop = 0; loop < ml->numsprites; loop++ )
   {
      curfld = &csprite [ loop ];
      curlib = &slib [ csprite [ loop ].game ] [ csprite [ loop ].slib ];

      if ( curfld->level & cur_diff )
      {
         for ( i = 0; i < curlib->num_frames; i++ )
            GLB_FreeItem ( curlib->item + ( DWORD )i );
      }
   }
}

/***************************************************************************
ENEMY_LoadSprites() - 
 ***************************************************************************/
VOID
ENEMY_LoadSprites (
VOID
)
{
   INT       loop, i;
   SPRITE *  curlib;
   CSPRITE * curfld;
   DWORD     item;

   ENEMY_Clear();
   cur_visable = 0;
   boss_sound = FALSE;

   for ( loop = 0; loop < ml->numsprites; loop++ )
   {
      curfld = &csprite [ loop ];
      curlib = &slib [ csprite [ loop ].game ] [ curfld->slib ];
      curlib->item = GLB_GetItemID ( curlib->iname );

      switch ( curfld->level )
      {
         default:
