88:CHAR     *key,             // INPUT : Key that will allow Decryption
89:BYTE     *buffer,          // INPUT : Buffer to Encrypt
90:size_t   length            // INPUT : Length of Buffer
91:)
92:{
93:   INT   klen = strlen( key );
94:   INT   prev_byte;
95:   INT   kidx;
96:  
97:   kidx = SEED % klen;
98:   prev_byte = key[ kidx ];
99:   while ( length-- )
100:   {
101:      prev_byte = ( *buffer + key[ kidx ] + prev_byte ) % 256;
102:      *buffer++ = prev_byte;
103:  
104:      if ( ++kidx >= klen )
105:         kidx = 0;
106:   }
107:}
