194:   GLB_OpenFile() - Opens & Caches file handle
195: ------------------------------------------------------------------------*/
196:PRIVATE INT
197:GLB_OpenFile(
198:INT	return_on_failure,	// INPUT : Don't bomb if file not open
199:INT	filenum,             // INPUT : file number
200:INT	permissions				// INPUT : file access permissions
201:)
202:{
203:   FILEDESC    *fd;
204:
205:   ASSERT( filenum >= 0 && filenum < MAX_GLB_FILES );
206:
207:   fd = &filedesc[ filenum ];
