PRIVATE VOID
GLB_CloseFiles(
VOID
)
{
	INT		j;

	for ( j = 0; j < MAX_GLB_FILES; j++ )
	{
      if ( filedesc[ j ].handle )
      {
   		close( filedesc[ j ].handle );
         filedesc[ j ].handle = 0;
      }
	}
}


