 ***************************************************************************/
VOID
IPT_FMovePlayer (
INT addx,                  // INPUT : add to x pos
INT addy                   // INPUT : add to y pos
)
{
   g_addx   = addx;
   g_addy   = addy;

   IPT_MovePlayer();
}

