// GLB archive parser for Apogee "GLB" files (used by Raptor shareware).
// Format (from GFX/GLBAPI.C):
//   Header KEYFILE (32 bytes, encrypted):
//     DWORD opt, DWORD numItems, DWORD filesize, char name[16]
//   Item table: numItems * KEYFILE (32 bytes each, encrypted):
//     DWORD opt (1 = encoded), DWORD offset, DWORD size, char name[16]
//   Encryption: running XOR-ish cipher with key "32768GLB", seed 0x19.
//
// Usage: node tools/glbparse.js <file.glb> [itemName|itemNumber ...]
const fs = require('fs');

const KEY = '32768GLB';
const SEED = 0x19;

function decrypt(buf, key) {
  const klen = key.length;
  let kidx = SEED % klen;
  let prev = key.charCodeAt(kidx);
  for (let i = 0; i < buf.length; i++) {
    const d = ((buf[i] - key.charCodeAt(kidx) - prev) % 256 + 256) % 256;
    prev = buf[i];
    buf[i] = d;
    if (++kidx >= klen) kidx = 0;
  }
  return buf;
}

class GLB {
  constructor(data, prefix) {
    this.data = data;
    this.items = [];
    const head = Buffer.from(data.subarray(0, 32));
    decrypt(head, KEY);
    const view = new DataView(head.buffer, head.byteOffset, 32);
    this.numItems = view.getUint32(4, true);
    const n = this.numItems;
    for (let i = 0; i < n; i++) {
      const off = 32 + i * 32;
      const rec = Buffer.from(data.subarray(off, off + 32));
      decrypt(rec, KEY);
      const v = new DataView(rec.buffer, rec.byteOffset, 32);
      const name = rec.subarray(8, 24);
      let nm = '';
      for (let j = 0; j < 16; j++) if (name[j]) nm += String.fromCharCode(name[j]); else break;
      this.items.push({
        opt: v.getUint32(0, true),
        offset: v.getUint32(4, true),
        size: v.getUint32(8, true),
        name: nm,
        encoded: (v.getUint32(0, true) & 0x40000000) || v.getUint32(0, true) === 1,
      });
    }
  }
  get(nameOrNum) {
    if (typeof nameOrNum === 'number') {
      const it = this.items[nameOrNum];
      if (!it) return null;
      let buf = Buffer.from(this.data.subarray(it.offset, it.offset + it.size));
      if (it.encoded) decrypt(buf, KEY);
      return buf;
    }
    const it = this.items.find((x) => x.name === nameOrNum);
    if (!it) return null;
    let buf = Buffer.from(this.data.subarray(it.offset, it.offset + it.size));
    if (it.encoded) decrypt(buf, KEY);
    return buf;
  }
  indexOf(name) {
    return this.items.findIndex((x) => x.name === name);
  }
}

module.exports = { GLB, decrypt, KEY };

if (require.main === module) {
  const [file, ...args] = process.argv.slice(2);
  const data = fs.readFileSync(file);
  const glb = new GLB(data);
  console.log(`items: ${glb.numItems}`);
  if (!args.length) {
    for (let i = 0; i < glb.items.length; i++) {
      const it = glb.items[i];
      console.log(`${i.toString(16).padStart(4, '0')}  ${it.name.padEnd(16)}  ${it.size}  @${it.offset}`);
    }
    return;
  }
  for (const a of args) {
    const buf = glb.get(/^\d+$/.test(a) ? parseInt(a, 16) : a);
    if (!buf) {
      console.log(`MISSING: ${a}`);
      continue;
    }
    console.log(`--- ${a} (${buf.length} bytes)`);
    const hex = [];
    for (let i = 0; i < Math.min(buf.length, 128); i++) hex.push(buf[i].toString(16).padStart(2, '0'));
    console.log(hex.join(' '));
  }
}

