      *ly = SCREENHEIGHT - *y;
   }
  
   if ( *x < 0 )
   {
      rval = 2;
      if ( image ) *image += -*x;
      *lx += *x;
      *x = 0;
   }

   if ( *x + *lx > SCREENWIDTH )
   {
      rval = 2;
      *lx = SCREENWIDTH - *x;
   }
  
   return ( rval );
}
  
/**************************************************************************
   GFX_SetVideoMode13() - sets 256 color 320x200 mode
 **************************************************************************/
VOID
GFX_SetVideoMode13(
VOID
)
{
   union REGS      r;
  
   r.w.ax = 0x13;
   int386 (0x10,(const union REGS *)&r,&r);
}
  
